INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "王行瑜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王行瑜。", "biography": null, "status": "draft", "id": "65e50f4b-8971-5070-b043-77c6748c1fc0"}, {"name": "韩建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“韩建出任司徒、同平章事”中为受任者。", "biography": null, "status": "draft", "id": "0a022fc7-47b3-5530-98ad-3625fceab9a5"}, {"name": "王行约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：王行约。", "biography": null, "status": "draft", "id": "e3ef8c5d-f45c-5024-998e-2dd76a19b8ae"}, {"name": "李茂庄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李茂庄。", "biography": null, "status": "draft", "id": "404cb408-7abf-5c26-b4b6-2ecc0b4a90c0"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李嗣勋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李嗣勋。", "biography": null, "status": "draft", "id": "04cf613f-bf1d-523b-8789-8444f1cfcb29"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "刘威", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“楚军击败刘存等淮南水军，攻取岳州”中为淮南应援使。", "biography": null, "status": "draft", "id": "17e4c5b9-67b6-514b-9eb8-1eb8aa66133f"}, {"name": "李神福", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李神福，在此段中为用疑兵解围者。", "biography": null, "status": "draft", "id": "61a41119-a9f8-5beb-8356-77ed00b4ae34"}, {"name": "戴友规", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：戴友规。", "biography": null, "status": "draft", "id": "7dae53fb-4ff2-5427-a7cb-dd57f79c3f34"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "杨晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨晟。", "biography": null, "status": "draft", "id": "93faf005-49ad-5fd8-82c5-75a556805ef0"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "吕尧", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：吕尧。", "biography": null, "status": "draft", "id": "f8a48067-6fa0-5061-928f-228887dbadd9"}, {"name": "杨守厚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：杨守厚。", "biography": null, "status": "draft", "id": "ce662852-3f90-558c-a2c2-7c69ea73d84f"}, {"name": "李简（王建将）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：李简（王建将）。", "biography": null, "status": "draft", "id": "fc932af9-eaac-525f-b99d-7fa7094d1553"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "朱友裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：朱友裕。", "biography": null, "status": "draft", "id": "fd61394b-01c5-5bba-9d50-af1029c306bc"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "西门君遂", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：西门君遂。", "biography": null, "status": "draft", "id": "ee5a7388-72a2-5742-ad8e-a61393243757"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "牛徽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：牛徽。", "biography": null, "status": "draft", "id": "f9d7e691-03d4-5150-9590-3534d7cf5aad"}, {"name": "张归厚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的张归厚，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "91fec634-2d73-519c-8547-b001a19cb85c"}, {"name": "李璠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李璠。", "biography": null, "status": "draft", "id": "0a7791be-f6ce-5a5b-a2d4-60c2d575d602"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朝廷赦天下改元景福", "start_year": 892, "end_year": 892, "time_original": "892年春正月丙寅", "dynasty": "唐", "description": "朝廷赦天下，改元景福。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d3f0edf1-db54-56ea-9639-924638dfcc73"}, {"title": "李茂贞等五帅请讨诸杨，朝廷令和解", "start_year": 892, "end_year": 892, "time_original": "892年正月条；具体日未载", "dynasty": "唐", "description": "李茂贞、王行瑜、韩建、王行约、李茂庄五节度使上言杨守亮容匿杨复恭，请出军讨之，并求授李茂贞山南西道招讨使。朝议恐李茂贞得山南难制，下诏和解，五帅不听。", "phases": [], "location_name": "凤翔、静难、镇国、同州、秦州、山南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "62493fa8-02ba-58a7-9441-731b367c8788"}, {"title": "李嗣勋尧山击败幽镇联军", "start_year": 892, "end_year": 892, "time_original": "892年正月条；具体日未载", "dynasty": "唐", "description": "王镕、李匡威合兵十余万攻尧山，李克用遣李嗣勋迎击，大破幽州镇州军，书载斩获三万。", "phases": [], "location_name": "尧山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52e239b7-3bf4-548a-a819-70cb7ce42cd4"}, {"title": "刘威李神福劝坚壁，戴友规劝遣民归淮", "start_year": 892, "end_year": 892, "time_original": "892年正月条；具体日未载", "dynasty": "唐", "description": "杨行密称孙儒兵十倍、自己多次不利，询是否退保铜官。刘威、李神福劝据险坚壁清野、抄粮饷；戴友规劝护送淮南士民归乡复业，使敌军思归。杨行密欣然采纳。", "phases": [], "location_name": "铜官、淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ff698ebe-251d-5f89-868c-bad3cfd2af6c"}, {"title": "杨晟约杨守亮等攻王建", "start_year": 892, "end_year": 892, "time_original": "892年二月丁丑前", "dynasty": "唐", "description": "杨晟与杨守亮等约定攻击王建。", "phases": [], "location_name": "威戎、山南、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eb6c622b-c852-578c-8a05-a03d7c6d339c"}, {"title": "杨晟掠新繁汉州，李简击斩吕尧", "start_year": 892, "end_year": 892, "time_original": "892年二月丁丑及其后", "dynasty": "唐", "description": "杨晟出军掠新繁汉州，遣吕尧率二千人会杨守厚攻梓州。王建遣行营都指挥使李简迎击吕尧，斩之。", "phases": [], "location_name": "新繁、汉州、梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "751511b3-dc72-5e2d-bec3-d39a5b8f1d0d"}, {"title": "朱全忠击朱瑄，遣朱友裕军斗门", "start_year": 892, "end_year": 892, "time_original": "892年二月戊寅", "dynasty": "唐", "description": "朱全忠出兵击朱瑄，遣其子朱友裕领兵先行，驻斗门。", "phases": [], "location_name": "斗门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "03c743ea-cb94-5140-b27b-1271137bddd8"}, {"title": "李茂贞王行瑜擅击兴元并凌朝廷", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "李茂贞与王行瑜未经诏命举兵攻兴元，李茂贞不断表求招讨使，又给杜让能、西门君遂写信凌蔑朝廷。", "phases": [], "location_name": "兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4a39ba97-62bd-529f-ba26-db7865408bb2"}, {"title": "牛徽请授招讨以约束，朝廷任李茂贞", "start_year": 892, "end_year": 892, "time_original": "892年二月条；延英议后", "dynasty": "唐", "description": "皇帝召宰相谏官议李茂贞，众不敢言。牛徽称其不应不待诏命，又称军过山南伤民甚多，建议授招讨以国法约束。皇帝采纳，任李茂贞山南西道招讨使。", "phases": [], "location_name": "延英、山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cafd6095-f423-5531-92fd-c80b3e1276ba"}, {"title": "朱瑄袭斗门，朱友裕弃营逃", "start_year": 892, "end_year": 892, "time_original": "892年二月甲申", "dynasty": "唐", "description": "朱全忠至卫南时，朱瑄率步骑万人袭斗门，朱友裕弃营逃走，朱瑄占其营。", "phases": [], "location_name": "卫南、斗门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "93aa04ee-46b1-5d6e-9922-14dd204d0b6c"}, {"title": "朱全忠不知斗门失营，引军遭袭退瓠河", "start_year": 892, "end_year": 892, "time_original": "892年二月乙酉", "dynasty": "唐", "description": "朱全忠不知斗门已为朱瑄占据，引军趋营，到者被郓州军杀，遂退驻瓠河。", "phases": [], "location_name": "斗门、瓠河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "224f030f-3970-5b6f-84f8-065fcc661cda"}, {"title": "朱瑄瓠河大破朱全忠，张归厚后战救免", "start_year": 892, "end_year": 892, "time_original": "892年二月丁亥", "dynasty": "唐", "description": "朱瑄进攻朱全忠并大败之，朱全忠逃走，张归厚在后力战，使朱全忠仅免；副使李璠等皆死。", "phases": [], "location_name": "瓠河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5d853090-e5e7-54e6-97b9-fe8511d80350"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "父亲", "description": "《通鉴》称朱友裕为朱全忠之子；朱温是朱友裕的父亲。", "status": "draft", "id": "3cf54e55-0823-5438-8372-53cef6aedd70", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "fd61394b-01c5-5bba-9d50-af1029c306bc"}]'::jsonb)
